package com.gamehub.application.controller;
import com.gamehub.application.OperationsService; import java.util.List;
public final class SessionController { private final OperationsService ops; public SessionController(OperationsService ops){this.ops=ops;} public List<String> reservations()throws Exception{return ops.eligibleReservationRecords();} public List<String> active()throws Exception{return ops.activeSessionRecords();} public List<String> customers()throws Exception{return ops.walkInCustomerRecords();} public List<String> stations()throws Exception{return ops.availableStationRecords();} public String bill(long id)throws Exception{return ops.sessionBill(id);} public long startReserved(long staff,long reservation)throws Exception{return ops.startSession(staff,reservation);} public long startWalkIn(long staff,long customer,long station,int minutes)throws Exception{return ops.startWalkInSession(staff,customer,station,minutes);} public void extend(long staff,long session,int minutes)throws Exception{ops.extendSession(staff,session,minutes);} public long finish(long staff,long session)throws Exception{return ops.finishSessionCalculated(staff,session);} }